    let mut g: f64 = (gmst + (dpsi * f64::cos(eps)));
    let mut rg: [[f64; 3]; 3] = [[f64::cos(g), f64::sin(g), 0.0], [(-(f64::sin(g))), f64::cos(g), 0.0], [0.0, 0.0, 1.0]];
    let mut xp: f64 = (eop[1] * as_);
    let mut yp: f64 = (eop[2] * as_);
    let mut ry: [[f64; 3]; 3] = [[f64::cos(xp), 0.0, f64::sin(xp)], [0.0, 1.0, 0.0], [(-(f64::sin(xp))), 0.0, f64::cos(xp)]];
    let mut rx: [[f64; 3]; 3] = [[1.0, 0.0, 0.0], [0.0, f64::cos(yp), (-(f64::sin(yp)))], [0.0, f64::sin(yp), f64::cos(yp)]];
    c = rt::mm(rt::mm(rt::mm(rx, ry), rg), rn);
