        let mut tb1: [f64; 3] = rt::unit(rt::cross(b1, b2));
        let mut tb2: [f64; 3] = rt::cross(tb0, tb1);
        let mut tr0: [f64; 3] = rt::unit(r1);
        let mut tr1: [f64; 3] = rt::unit(rt::cross(r1, r2));
        let mut tr2: [f64; 3] = rt::cross(tr0, tr1);
        let mut a: [[f64; 3]; 3] = [[0.0; 3]; 3];
